changes.beforeContent:
(def css "
:root{
  --ground:#191513; --raised:#221d19; --sunk:#141110;
  --ink:#ece5da; --muted:#a2988a; --rule:#332b24;
  --add:#56B4E9; --del:#E69F00; --green:#009E73; --verm:#D55E00;
  --purple:#CC79A7; --yellow:#F0E442; --blue:#0072B2;
}
*{box-sizing:border-box}
html{color-scheme:dark;-webkit-text-size-adjust:100%}
body{
  margin:0;padding:1.5rem 1rem 4rem;
  background:var(--ground);color:var(--ink);
  font-family:Newsreader,'Iowan Old Style','Source Serif Pro',Georgia,serif;
  font-size:1.0625rem;line-height:1.55;text-align:left;
}
main{max-width:46rem;margin:0 auto;overflow-wrap:anywhere}
h1{font-size:1.65rem;line-height:1.25;margin:.2rem 0 .9rem;font-weight:600}
h2{font-size:1.05rem;margin:0 0 .35rem;font-weight:600;letter-spacing:.01em}
p{margin:0 0 .7rem}
a{color:var(--add)}
code,pre,.cmd,.hhash,.hrange{
  font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  font-size:.82em;
}
.eyebrow{color:var(--muted);font-size:.85rem;letter-spacing:.06em;
  text-transform:uppercase;margin:0}
.eyebrow .pid{text-transform:none;letter-spacing:0}
.lede .thesis{font-style:italic;font-size:1.15rem;line-height:1.45;color:var(--ink)}
.lede .folded{color:var(--muted);font-size:.95rem}
.scope{margin:0 0 .6rem}
.scope ul{margin:.2rem 0 0;padding-left:1.2rem}
.overview{margin:1rem 0 0}
.overview .chip,.arg h2 .chip{vertical-align:middle}
.also{color:var(--muted);font-size:.95rem}
.arg{margin:3rem 0 0;padding-top:1.3rem;border-top:1px solid var(--rule)}
.arg.core{border-top:3px solid var(--green)}
.arg.supporting{border-top-color:var(--blue)}
.arg h2{font-size:1.3rem;line-height:1.3;margin:0 0 .6rem}
.arg .arg-title{font-size:1.15rem;margin:0}
.arg .contribution{color:var(--ink);font-style:italic}
.evidence{margin:.8rem 0 1.2rem}
.evidence figcaption{margin:0 0 .4rem}
.next{margin:1.6rem 0 .4rem;padding:.65rem .8rem;background:var(--sunk);
  border:1px solid var(--rule);border-left:4px solid var(--green);border-radius:4px}
.next-to{display:flex;flex-wrap:wrap;align-items:baseline;gap:.2rem .5rem;
  margin:0 0 .3rem;font-weight:600}
.next .arrow{color:var(--green)}
.next-why{margin:0}
a:focus-visible,summary:focus-visible,button:focus-visible{
  outline:2px solid var(--yellow);outline-offset:2px;border-radius:2px}
.i-core{color:var(--green)} .i-supporting{color:var(--blue)} .i-incidental{color:var(--muted)}
.summary-row{display:flex;flex-wrap:wrap;gap:.15rem 1.4rem;margin:1rem 0;
  padding:.6rem 0;border-top:1px solid var(--rule);border-bottom:1px solid var(--rule)}
.summary-row .stat{display:flex;gap:.4rem;align-items:baseline}
.summary-row dt{color:var(--muted);font-size:.8rem;text-transform:uppercase;
  letter-spacing:.05em}
.summary-row dd{margin:0;font-variant-numeric:tabular-nums}
.sec{margin:2.2rem 0 0;padding-top:1.1rem;border-top:1px solid var(--rule)}
.sec-note,.empty{color:var(--muted);font-size:.92rem}
.hunk{margin:.5rem 0 1rem;background:var(--raised);border:1px solid var(--rule);
  border-radius:4px;overflow:hidden}
.hunk-head{display:flex;flex-wrap:wrap;align-items:center;gap:.4rem .6rem;
  padding:.45rem .6rem;border-bottom:1px solid var(--rule);background:var(--sunk)}
.hid{font-family:ui-monospace,monospace;font-size:.82rem;font-weight:600;
  color:var(--ink);text-decoration:none}
.hid:hover{text-decoration:underline}
.hfile{font-size:.88rem;color:var(--ink)}
.hrange{color:var(--muted)}
.hhash{color:var(--muted);opacity:.6;font-size:.75rem;margin-left:auto}
.chip{font-family:ui-monospace,monospace;font-size:.68rem;letter-spacing:.04em;
  text-transform:uppercase;padding:.1rem .35rem;border-radius:3px;
  border:1px solid currentColor;white-space:nowrap}
.c-code{color:var(--muted)} .c-lockfile{color:var(--purple)}
.c-generated{color:var(--yellow)} .c-formatting-only{color:var(--muted)}
.c-binary,.c-rename,.c-mode-change{color:var(--verm)}
.c-rep{color:var(--green)}
.r-repeated-pattern{color:var(--green)} .r-lockfile{color:var(--purple)}
.r-mechanical{color:var(--muted)} .r-generated{color:var(--yellow)}
.r-formatting-only{color:var(--muted)} .r-raw{color:var(--muted)}
.t-pass{color:var(--green)} .t-fail{color:var(--verm)}
.t-partial{color:var(--yellow)} .t-not-run{color:var(--muted)}
.s-added{color:var(--green)} .s-modified{color:var(--muted)}
.s-deleted{color:var(--verm)} .s-renamed,.s-copied{color:var(--purple)}
.chip.w{color:var(--yellow)}
.patch{margin:0;padding:.5rem 0;overflow-x:auto;background:var(--raised);
  line-height:1.25;-webkit-overflow-scrolling:touch}
.patch code{display:block;min-width:max-content}
.ln{display:block;padding:0 .6rem;white-space:pre}
.ln.add{color:var(--add);background:rgba(86,180,233,.09)}
.ln.del{color:var(--del);background:rgba(230,159,0,.09)}
.ln.header{color:var(--muted);background:var(--sunk)}
.ln.meta{color:var(--muted)}
.ln.ctx{color:var(--ink);opacity:.82}
.patch.raw{max-height:none}
.synthetic{margin:.5rem .6rem;color:var(--muted);font-size:.92rem}
.files{list-style:none;margin:.8rem 0 0;padding:0}
.file{padding:.5rem 0;border-bottom:1px solid var(--rule);
  display:flex;flex-wrap:wrap;align-items:baseline;gap:.35rem .6rem}
.file .path{font-size:.9em;color:var(--ink)}
.file .counts{color:var(--muted);font-size:.85rem;font-variant-numeric:tabular-nums}
.counts .add{color:var(--add)} .counts .del{color:var(--del)}
.role{flex-basis:100%;margin:.15rem 0 0;color:var(--muted);font-size:.95rem}
.group{margin:.9rem 0;border:1px solid var(--rule);border-radius:4px;
  background:var(--raised)}
.group>summary{cursor:pointer;padding:.55rem .6rem;list-style:none;
  display:flex;flex-wrap:wrap;align-items:baseline;gap:.4rem .5rem}
.group>summary::-webkit-details-marker{display:none}
.group>summary::before{content:'-';color:var(--muted);font-family:monospace}
.group:not([open])>summary::before{content:'+'}
.gnote{color:var(--muted);font-size:.92rem;flex-basis:100%}
.group>*:not(summary){margin-left:.6rem;margin-right:.6rem}
.group .hunk{margin-bottom:.6rem}
.differences{color:var(--muted);font-size:.95rem;margin-top:.2rem}
.tag{color:var(--green);font-size:.7rem;text-transform:uppercase;
  letter-spacing:.05em;font-family:ui-monospace,monospace}
.prose-list{margin:.8rem 0 0;padding-left:1.2rem}
.prose-list li{margin:0 0 .45rem}
.tests{list-style:none;margin:.8rem 0 0;padding:0}
.tests li{padding:.4rem 0;border-bottom:1px solid var(--rule);
  display:flex;flex-wrap:wrap;align-items:baseline;gap:.4rem .6rem}
.cmd.none{color:var(--muted);font-style:italic}
.copy{display:none;font:inherit;font-size:.7rem;font-family:ui-monospace,monospace;
  text-transform:uppercase;letter-spacing:.04em;color:var(--muted);
  background:transparent;border:1px solid var(--rule);border-radius:3px;
  padding:.15rem .35rem;cursor:pointer}
.js .copy{display:inline-block}
.copy:hover{color:var(--ink);border-color:var(--muted)}
.foot{margin:2.5rem 0 0;padding-top:1.1rem;border-top:1px solid var(--rule);
  color:var(--muted);font-size:.85rem}
.foot p{margin:0 0 .3rem}
.versions{opacity:.7}
.history{margin:.6rem 0 1rem;padding:.6rem .7rem;border:1px solid var(--rule);
  border-left:3px solid var(--blue);border-radius:4px;background:var(--raised)}
.history p{margin:0 0 .4rem}
.history-rows{margin:0;padding-left:1.4rem;font-size:.92rem}
.hrow{margin:0 0 .4rem}
.hrow .hstep{margin:.1rem 0 0}
.hstate,.restored{color:var(--muted);font-style:italic}
.resp{color:var(--muted)} .r-approved{color:var(--green)} .r-feedback{color:var(--del)}
.r-current{color:var(--yellow)}
.since-files{margin:.3rem 0 .7rem;padding-left:1.2rem}
.since-files li{margin:0 0 .25rem}
.banner{margin:.8rem 0;padding:.6rem .7rem;border:1px solid var(--rule);
  border-left:3px solid var(--del);border-radius:4px;background:var(--raised)}
.full-cta{margin:.8rem 0;padding:.6rem .7rem;border:1px solid var(--rule);
  border-left:3px solid var(--green);border-radius:4px;background:var(--raised)}
.full-cta p{margin:0 0 .4rem}
.full-link{font-size:1.15rem;font-weight:600}
@media (min-width:40rem){
  body{padding:2.5rem 2rem 5rem;font-size:1.125rem}
  h1{font-size:2rem}
}
")

